var STEPS = [
  {
    n: 1,
    title: "Residual stream after attention",
    short: "h after mixer",
    kind: "stream",
    sources: ["hf-decoder-layer"],
    detail: `The layer's input h has already passed through input_layernorm and the token mixer (Gated DeltaNet or full attention) and been added back: h_mid = h + mixer(norm(h)). h_mid is a ${HIDDEN.toLocaleString()}-vector per token position. One copy continues down the skip path unchanged.`
  },
  {
    n: 2,
    title: "RMSNorm",
    short: "post_attention_layernorm",
    kind: "op",
    sources: ["hf-decoder-layer"],
    detail: "A copy of h_mid is normalised by post_attention_layernorm (RMSNorm with a zero-centred weight, output \xD7 (1 + weight)). Only this copy enters the MLP; the skip path keeps the un-normalised h_mid."
  },
  {
    n: 3,
    title: "gate_proj and up_proj",
    short: "two linear maps",
    kind: "op",
    sources: ["hf-mlp"],
    detail: `Two linear maps take the normalised ${HIDDEN.toLocaleString()}-vector to ${INTERMEDIATE.toLocaleString()} numbers each: gate = gate_proj(x) and up = up_proj(x).`
  },
  {
    n: 4,
    title: "Gated activation z = SiLU(gate) \u2299 up",
    short: "z, 9,216 wide",
    kind: "op",
    sources: ["hf-mlp"],
    detail: `Elementwise: z[i] = SiLU(gate[i]) \xB7 up[i]. These ${INTERMEDIATE.toLocaleString()} numbers per token are "the MLP neuron activations" in this project (a_t). They are the input of down_proj.`
  },
  {
    n: 5,
    title: "Intervention: z[n] \u2190 z[n] + \u03B1",
    short: "+ \u03B1 \xB7 e\u2099  (before down_proj)",
    kind: "hook",
    sources: ["hook-add", "push-unit", "hook-register"],
    detail: "A forward pre-hook on down_proj receives z, clones it, and adds the dose-derived constant \u03B1 to coordinate n only. It runs on every position of the forward input: all prompt positions during prefill, then the one new token at each decode step. The batch carries three rows with signs +1, 0 and \u22121, so one call produces the recipe, baseline and reversed branches."
  },
  {
    n: 6,
    title: "down_proj",
    short: "W_down \xB7 z",
    kind: "op",
    sources: ["hf-mlp", "down-column"],
    detail: "down_proj is linear and has no bias, so the extra \u03B1 at coordinate n contributes exactly \u03B1 \xB7 W_down[:, n] = \u03B1\xB7w to the MLP output, a vector in the residual space. That is the whole effect on this layer: \u0394r = \u03B1\xB7w."
  },
  {
    n: 7,
    title: "Residual addition",
    short: "h_out = h_mid + MLP out",
    kind: "op",
    sources: ["hf-decoder-layer"],
    detail: "The MLP output joins the skip path: h_out = h_mid + down_proj(z\u2032). Layer L+1 reads h_out. Later layers see the change through their own norms, attention and MLPs; the push is not re-applied there unless the recipe lists that layer."
  },
  {
    n: 8,
    title: "Port: control vector after step 7",
    short: "llama.cpp build_cvec",
    kind: "port",
    sources: ["llama-cvec-call", "llama-cvec-apply", "llama-cvec-parse"],
    detail: "llama.cpp has no neuron hook. The exported GGUF stores \u03B1\xB7w per layer as direction.L, and build_cvec adds it after the layer's FFN residual addition. Because step 6 and step 7 are linear, this equals step 5 exactly in real arithmetic. The vectors are derived from BF16 weights; on a quantized model it is a port, not the same intervention."
  }
];
